def test_geodesic_transport_independent_tensor_oracle():
    loc = np.array([[.3,.7],[1.2,2.1],[2.7,5.1]])
    end,p0,p1 = spherical_pairs(loc,[3.],[47.])
    n,s,e = local_frame(loc)
    n1,s1,e1 = local_frame(end[0,0])
    a = np.array([1+2j,-.7+.2j,3-.5j])
    values = []
    for j in range(3):
        axis = np.cross(n[j],n1[j]);axis /= np.linalg.norm(axis)
        skew = np.array([[0,-axis[2],axis[1]],[axis[2],0,-axis[0]],[-axis[1],axis[0],0]])
        angle = np.radians(3.)
        rot = np.eye(3)+np.sin(angle)*skew+(1-np.cos(angle))*(skew@skew)
        tensor = a[j].real*(np.outer(s[j],s[j])-np.outer(e[j],e[j]))+a[j].imag*(np.outer(s[j],e[j])+np.outer(e[j],s[j]))
        tensor = rot@tensor@rot.T
        values.append(s1[j]@tensor@s1[j]+1j*(s1[j]@tensor@e1[j]))
    view = increment_views(a[None],np.array(values)[None,None,None],p0,p1)
    assert np.max(np.abs(view[0]))<1e-12
    assert np.max(np.abs(view[1]))>.01


def test_local_basis_gauge_cancels():
    rng = np.random.default_rng(8211)
    a,b = rng.normal(size=(2,1,12))+1j*rng.normal(size=(2,1,12))
    _,p0,p1 = spherical_pairs(np.column_stack([np.full(12,.6),np.linspace(0,6,12)]),[2.],[35.])
    beta0,beta1 = rng.normal(size=(2,12))
    expected = increment_views(a,b[:,None,None],p0,p1)[0]
    changed = increment_views(a*np.exp(-2j*beta0),b[:,None,None]*np.exp(-2j*beta1),p0*np.exp(2j*beta0),p1*np.exp(2j*beta1))[0]
    assert np.max(np.abs(expected-changed))<1e-12


def test_gaussian_wick_and_heavy_tail_positive_control():
    rng = np.random.default_rng(348180)
    z = rng.normal(size=(3,100000))+1j*rng.normal(size=(3,100000))
    a,b = z[0]+.3*z[1],z[0]+.4*z[2]
    baseline = cross_statistics(a,b)
    assert abs(baseline[6])<.05
    scale = np.where(np.arange(len(a))%5==0,3.,1.)
    positive = cross_statistics(a*scale,b*scale)
    assert positive[6]>.5
    assert abs(baseline[3]-baseline[4]-baseline[2])<1e-12


def test_deterministic_four_sample_moments_and_invalid_inputs():
    z = np.array([-1,1,-1,1],dtype=complex)
    result = cross_statistics(z,z)
    assert np.array_equal(result,[1,1,1,1,0,1,-2,0])
    try:
        cross_statistics(z,z*0)
    except ValueError:
        pass
    else:
        raise AssertionError('degenerate variance accepted')


def test_recorded_actual_gpus():
    assert GPU_ATTESTATION is not None
    rng = np.random.default_rng(920053)
    a,b = rng.normal(size=(2,1024))+1j*rng.normal(size=(2,1024))
    expected = cross_statistics(a,b)
    features = rng.normal(size=(4,4,5,4,8))
    indices = rng.integers(0,5,size=(2,5))
    bootstrap = bootstrap_tiles(features,indices)
    for device in GPU_ATTESTATION['devices']:
        assert np.max(np.abs(np.asarray(device['statistics'])-expected)/(1+np.abs(expected)))<1e-10
        assert np.max(np.abs(np.asarray(device['bootstrap'])-bootstrap)/(1+np.abs(bootstrap)))<1e-10
